# Modular Distributed SQL Query Execution Engine in C#

Below is a design for a modular distributed SQL query execution engine in C# with the three requested components. This implementation uses a pipeline architecture where operators process data sequentially.

## Core Architecture Overview

```csharp
public interface IQueryOperator
{
    Task ProcessAsync(QueryContext context);
    Task InitializeAsync();
    Task ShutdownAsync();
}

public class QueryContext
{
    public IReadOnlyList<Partition> InputPartitions { get; set; }
    public IReadOnlyList<Partition> OutputPartitions { get; set; }
    public MemoryManager MemoryManager { get; }
    public CancellationToken CancellationToken { get; }
    // Other context properties...
}
```

## 1. Network Exchange Operator

Handles buffering and routing data partitions between nodes:

```csharp
public class NetworkExchangeOperator : IQueryOperator
{
    private readonly INodeCommunication _communication;
    private readonly IPartitionRouter _router;
    private readonly IBufferManager _bufferManager;
    private readonly int _bufferSize;

    public NetworkExchangeOperator(
        INodeCommunication communication,
        IPartitionRouter router,
        IBufferManager bufferManager,
        int bufferSize = 1024)
    {
        _communication = communication ?? throw new ArgumentNullException(nameof(communication));
        _router = router ?? throw new ArgumentNullException(nameof(router));
        _bufferManager = bufferManager ?? throw new ArgumentNullException(nameof(bufferManager));
        _bufferSize = bufferSize;
    }

    public async Task InitializeAsync()
    {
        // Initialize communication channels
        await _communication.InitializeAsync();
    }

    public async Task ProcessAsync(QueryContext context)
    {
        // Receive partitions from other nodes
        var receivedPartitions = await _communication.ReceivePartitionsAsync(
            context.CancellationToken);

        // Route partitions to appropriate operators
        var routedPartitions = _router.RoutePartitions(receivedPartitions);

        // Buffer partitions for downstream operators
        var bufferedPartitions = _bufferManager.BufferPartitions(
            routedPartitions, _bufferSize);

        // Output to next operator
        context.OutputPartitions = bufferedPartitions;
    }

    public async Task ShutdownAsync()
    {
        await _communication.ShutdownAsync();
    }
}

// Supporting interfaces
public interface INodeCommunication
{
    Task InitializeAsync();
    Task<IEnumerable<Partition>> ReceivePartitionsAsync(CancellationToken ct);
    Task ShutdownAsync();
}

public interface IPartitionRouter
{
    IEnumerable<Partition> RoutePartitions(IEnumerable<Partition> partitions);
}

public interface IBufferManager
{
    IEnumerable<Partition> BufferPartitions(IEnumerable<Partition> partitions, int bufferSize);
}
```

## 2. Hash Aggregation Operator

Groups records in memory with spill-to-disk capability:

```csharp
public class HashAggregationOperator : IQueryOperator
{
    private readonly Func<Record, object> _keySelector;
    private readonly Func<Record, Record, Record> _aggregator;
    private readonly IDiskSpillManager _spillManager;
    private readonly int _memoryLimit;
    private readonly int _spillThreshold;

    public HashAggregationOperator(
        Func<Record, object> keySelector,
        Func<Record, Record, Record> aggregator,
        IDiskSpillManager spillManager,
        int memoryLimit = 1024 * 1024 * 100, // 100MB
        int spillThreshold = 80) // 80% of memory limit
    {
        _keySelector = keySelector ?? throw new ArgumentNullException(nameof(keySelector));
        _aggregator = aggregator ?? throw new ArgumentNullException(nameof(aggregator));
        _spillManager = spillManager ?? throw new ArgumentNullException(nameof(spillManager));
        _memoryLimit = memoryLimit;
        _spillThreshold = spillThreshold;
    }

    public async Task InitializeAsync()
    {
        // Initialize spill manager
        await _spillManager.InitializeAsync();
    }

    public async Task ProcessAsync(QueryContext context)
    {
        var hashTable = new ConcurrentDictionary<object, Record>();
        var spillFiles = new List<string>();
        var currentMemoryUsage = 0;

        foreach (var partition in context.InputPartitions)
        {
            foreach (var record in partition.Records)
            {
                var key = _keySelector(record);

                // Check if we need to spill
                if (currentMemoryUsage > _memoryLimit * _spillThreshold / 100)
                {
                    await SpillHashTable(hashTable, spillFiles, context);
                    currentMemoryUsage = 0;
                }

                // Try to add to hash table
                if (hashTable.TryAdd(key, record))
                {
                    currentMemoryUsage += record.Size;
                }
                else
                {
                    // Update existing record
                    var existing = hashTable[key];
                    var newRecord = _aggregator(existing, record);
                    hashTable[key] = newRecord;
                    currentMemoryUsage += newRecord.Size - existing.Size;
                }
            }
        }

        // Spill any remaining data
        if (hashTable.Count > 0)
        {
            await SpillHashTable(hashTable, spillFiles, context);
        }

        // Merge spilled files with remaining in-memory data
        var resultPartitions = await _spillManager.MergeResults(spillFiles, hashTable);
        context.OutputPartitions = resultPartitions;
    }

    private async Task SpillHashTable(
        ConcurrentDictionary<object, Record> hashTable,
        List<string> spillFiles,
        QueryContext context)
    {
        var spillFile = await _spillManager.CreateSpillFile(context);
        spillFiles.Add(spillFile);

        foreach (var kvp in hashTable)
        {
            await _spillManager.WriteRecordToFile(kvp.Value, spillFile);
        }

        hashTable.Clear();
    }

    public async Task ShutdownAsync()
    {
        await _spillManager.ShutdownAsync();
    }
}
```

## 3. Disk Spill Manager

Handles spilling intermediate hash tables to disk:

```csharp
public class DiskSpillManager : IDiskSpillManager
{
    private readonly string _spillDirectory;
    private readonly int _maxSpillFiles;
    private readonly IFileSystem _fileSystem;
    private readonly int _recordSize;

    public DiskSpillManager(
        string spillDirectory,
        int maxSpillFiles = 100,
        IFileSystem fileSystem = null,
        int recordSize = 1024)
    {
        _spillDirectory = spillDirectory ?? throw new ArgumentNullException(nameof(spillDirectory));
        _maxSpillFiles = maxSpillFiles;
        _fileSystem = fileSystem ?? new FileSystem();
        _recordSize = recordSize;
    }

    public async Task InitializeAsync()
    {
        await _fileSystem.EnsureDirectoryExistsAsync(_spillDirectory);
    }

    public async Task<string> CreateSpillFile(QueryContext context)
    {
        var fileName = Path.Combine(_spillDirectory, $"spill_{Guid.NewGuid()}.dat");
        await _fileSystem.CreateFileAsync(fileName);
        return fileName;
    }

    public async Task WriteRecordToFile(Record record, string filePath)
    {
        var bytes = record.Serialize();
        await _fileSystem.AppendAllBytesAsync(filePath, bytes);
    }

    public async Task<IEnumerable<Partition>> MergeResults(
        IEnumerable<string> spillFiles,
        ConcurrentDictionary<object, Record> inMemoryData)
    {
        var resultPartitions = new List<Partition>();
        var currentPartition = new Partition();
        var currentPartitionSize = 0;

        // Add in-memory data first
        foreach (var kvp in inMemoryData)
        {
            if (currentPartitionSize + kvp.Value.Size > _recordSize)
            {
                resultPartitions.Add(currentPartition);
                currentPartition = new Partition();
                currentPartitionSize = 0;
            }

            currentPartition.Records.Add(kvp.Value);
            currentPartitionSize += kvp.Value.Size;
        }

        if (currentPartition.Records.Count > 0)
        {
            resultPartitions.Add(currentPartition);
        }

        // Process spilled files
        foreach (var file in spillFiles)
        {
            var records = await _fileSystem.ReadAllRecordsAsync(file, _recordSize);
            foreach (var record in records)
            {
                if (currentPartitionSize + record.Size > _recordSize)
                {
                    resultPartitions.Add(currentPartition);
                    currentPartition = new Partition();
                    currentPartitionSize = 0;
                }

                currentPartition.Records.Add(record);
                currentPartitionSize += record.Size;
            }

            await _fileSystem.DeleteFileAsync(file);
        }

        if (currentPartition.Records.Count > 0)
        {
            resultPartitions.Add(currentPartition);
        }

        return resultPartitions;
    }

    public async Task ShutdownAsync()
    {
        // Clean up any temporary files
        var files = await _fileSystem.GetFilesAsync(_spillDirectory);
        foreach (var file in files)
        {
            await _fileSystem.DeleteFileAsync(file);
        }
    }
}

public interface IDiskSpillManager
{
    Task InitializeAsync();
    Task<string> CreateSpillFile(QueryContext context);
    Task WriteRecordToFile(Record record, string filePath);
    Task<IEnumerable<Partition>> MergeResults(IEnumerable<string> spillFiles, ConcurrentDictionary<object, Record> inMemoryData);
    Task ShutdownAsync();
}

public interface IFileSystem
{
    Task EnsureDirectoryExistsAsync(string directory);
    Task CreateFileAsync(string filePath);
    Task AppendAllBytesAsync(string filePath, byte[] bytes);
    Task<IEnumerable<Record>> ReadAllRecordsAsync(string filePath, int recordSize);
    Task DeleteFileAsync(string filePath);
    Task<IEnumerable<string>> GetFilesAsync(string directory);
}
```

## Query Execution Pipeline

Here's how these components would work together:

```csharp
public class QueryExecutor
{
    private readonly IEnumerable<IQueryOperator> _operators;
    private readonly QueryContext _context;

    public QueryExecutor(IEnumerable<IQueryOperator> operators, QueryContext context)
    {
        _operators = operators ?? throw new ArgumentNullException(nameof(operators));
        _context = context ?? throw new ArgumentNullException(nameof(context));
    }

    public async Task ExecuteAsync()
    {
        foreach (var operator in _operators)
        {
            await operator.InitializeAsync();
        }

        try
        {
            foreach (var operator in _operators)
            {
                await operator.ProcessAsync(_context);
            }
        }
        finally
        {
            foreach (var operator in _operators.Reverse())
            {
                await operator.ShutdownAsync();
            }
        }
    }
}
```

## Example Usage

```csharp
// Setup
var context = new QueryContext
{
    InputPartitions = GetInitialPartitions(),
    MemoryManager = new MemoryManager(1024 * 1024 * 200), // 200MB
    CancellationToken = CancellationToken.None
};

// Create operators
var communication = new NodeCommunication();
var router = new PartitionRouter();
var bufferManager = new BufferManager();
var spillManager = new DiskSpillManager("spill_directory");

var networkExchange = new NetworkExchangeOperator(
    communication,
    router,
    bufferManager);

var hashAggregator = new HashAggregationOperator(
    record => record.Key,
    (existing, newRecord) => new Record { Key = existing.Key, Value = existing.Value + newRecord.Value },
    spillManager);

var operators = new List<IQueryOperator>
{
    networkExchange,
    hashAggregator
};

var executor = new QueryExecutor(operators, context);
await executor.ExecuteAsync();
```

## Key Features

1. **Modular Design**: Each component is independent and can be replaced or extended
2. **Memory Management**: Automatic spill-to-disk when memory limits are approached
3. **Partition Handling**: Efficient routing and buffering of data partitions
4. **Asynchronous Processing**: Non-blocking operations for better performance
5. **Resource Cleanup**: Proper shutdown procedures for all components

This architecture provides a foundation that can be extended with additional operators (projection, filtering, sorting) and optimized for specific workloads.
